import json,sys
f=sys.argv[1];out=open(sys.argv[2],'w')
def txt(c):
    if isinstance(c,str):return c
    return ' '.join(x.get('text','') if isinstance(x,dict) else str(x) for x in c)
pend={}
i=0
for line in open(f,errors='ignore'):
    i+=1
    try:o=json.loads(line)
    except:continue
    t=o.get('type');ts=(o.get('timestamp') or '')[:19]
    m=o.get('message')
    if not isinstance(m,dict):continue
    c=m.get('content')
    side='S' if o.get('isSidechain') else 'M'
    if t=='user':
        if isinstance(c,str):
            out.write(f"{i} {ts} {side} USER: {c[:1500]!r}\n")
        elif isinstance(c,list):
            for x in c:
                if x.get('type')=='text':
                    out.write(f"{i} {ts} {side} USER: {x['text'][:1500]!r}\n")
                elif x.get('type')=='tool_result':
                    tid=x.get('tool_use_id')
                    if tid in pend:
                        out.write(f"{i} {ts} {side} RESULT[{pend.pop(tid)}]: {txt(x.get('content'))[:1200]!r}\n")
    elif t=='assistant' and isinstance(c,list):
        for x in c:
            if x.get('type')=='text' and x['text'].strip():
                out.write(f"{i} {ts} {side} ASST: {x['text'][:800]!r}\n")
            elif x.get('type')=='tool_use':
                n=x['name'];inp=x['input']
                if n in('Agent','Task'):
                    pend[x['id']]=inp.get('subagent_type')
                    out.write(f"{i} {ts} {side} AGENT[{inp.get('subagent_type')}] {inp.get('description')}: {str(inp.get('prompt'))[:700]!r}\n")
                elif n=='Skill':
                    out.write(f"{i} {ts} {side} SKILL {inp}\n")
                elif n.startswith('mcp__playwright') or n=='Artifact':
                    out.write(f"{i} {ts} {side} TOOL {n} {str(inp)[:150]}\n")
